const arrow='<span aria-hidden="true">↗</span>';
const logo='<span class="brand-symbol" aria-hidden="true">✳</span> adcraft<span class="brand-dot">.</span>';
const pathname=location.pathname;const isPricing=pathname.includes('pricing');const isShowcase=pathname.includes('showcase');
const creative=[{id:'glow',title:'A little glow goes a long way.',brand:'ÉCLAT SKIN',type:'Static ads',panel:0,style:'glow',label:'Your daily dose<br>of <em>golden hour.</em>',description:'A warm, product-first concept that lets texture and light do the talking.',hook:'Meet your new morning ritual.',cta:'Find your glow',format:'4:5 · Feed ad'},{id:'routine',title:'The routine worth sharing.',brand:'ÉCLAT SKIN',type:'UGC videos',panel:1,style:'routine',label:'“Okay, I finally get<br>the hype.”',description:'An approachable creator-led concept built around a real-feeling daily routine.',hook:'I changed one thing in my morning routine.',cta:'Meet your everyday essential',format:'9:16 · UGC concept'},{id:'move',title:'Made for your next move.',brand:'STRIDE®',type:'Product videos',panel:2,style:'move',label:'LESS SCROLL.<br>MORE <em>GO.</em>',description:'A bold movement-led direction with vivid color and a single clear message.',hook:'Your next move starts here.',cta:'Make your move',format:'9:16 · Product concept'},{id:'sound',title:'Find your own frequency.',brand:'FORM AUDIO',type:'Static ads',panel:3,style:'sound',label:'Good sound.<br><em>Great escape.</em>',description:'A clean editorial composition that makes one product feel like a whole world.',hook:'A little less noise. A little more you.',cta:'Find your frequency',format:'4:5 · Feed ad'}];
const nav=()=>`<header class="site-header"><a class="brand" href="/" aria-label="Adcraft home">${logo}</a><nav class="desktop-nav" aria-label="Main navigation"><a href="/#possibilities">Platform</a><a ${isShowcase?'aria-current="page"':''} href="/showcase/">Creative showcase</a><a href="/#workflow">How it works</a><a ${isPricing?'aria-current="page"':''} href="/pricing/">Pricing</a></nav><a class="button button-small button-dark header-cta" href="/showcase/">Explore the studio ${arrow}</a><button class="menu-toggle" aria-label="Open navigation" aria-expanded="false">☰</button></header>`;
const art=(c,extra='')=>`<div class="ad-art ${c.style} ${extra}" style="--panel:${c.panel*100/3}%"><span class="ad-brand">${c.brand}</span><div class="ad-headline">${c.label}</div><span class="ad-caption">${c.cta} <span>↗</span></span></div>`;
const card=(c)=>`<button class="creative-card" data-creative="${c.id}" aria-label="View ${c.title}">${art(c)}<span class="card-bottom"><span>${c.type}</span><span aria-hidden="true">↗</span></span></button>`;
const footer=()=>`<footer class="site-footer"><div class="footer-top"><div><a class="brand" href="/">${logo}</a><p>A little creative.<br>A lot of possibility.</p></div><div class="footer-links"><div><span>THE PLATFORM</span><a href="/showcase/">Creative studio</a><a href="/#workflow">How it works</a><a href="/pricing/">Pricing</a></div><div><span>MADE FOR YOUR IDEAS</span><a href="/showcase/?format=Static%20ads">Static ads</a><a href="/showcase/?format=UGC%20videos">UGC videos</a><a href="/showcase/?format=Product%20videos">Product videos</a></div></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Adcraft</span><span>Early product preview. All showcased brands and ads are illustrative.</span><span>Made for the next big idea. ✳</span></div></footer>`;
const cta=()=>`<section class="final-cta"><div class="eyebrow">THE NEXT ONE COULD BE THE ONE.</div><h2>Less blank canvas.<br><em>More “let’s try this.”</em></h2><a class="button button-dark" href="/showcase/">Find your creative spark ${arrow}</a><span class="cta-spark" aria-hidden="true">✳</span></section>`;
const home=()=>`<main id="main"><section class="hero"><div class="eyebrow"><span class="tiny-star">✳</span> BIG IDEAS. SMALL PRODUCTION TEAM.</div><h1>Your next great ad.<br><em>Just an idea away.</em></h1><p>From “what if” to “that’s the one.” Create beautiful ads,<br class="desktop-break"> find your next winning angle, and keep the ideas coming.</p><div class="hero-actions"><a class="button button-orange" href="/showcase/">Find your creative spark ${arrow}</a><a class="text-button" href="#workflow"><span class="play-small">▶</span> See how it works</a></div><div class="hero-note">Your product. Your brand. A whole new world of possibilities.</div></section>
<section class="creative-wall" aria-label="Sample ad creative"><div class="floating-label"><span>✳</span> A few ideas to get you going</div><div class="wall-grid"><div class="type-ad"><span class="ad-brand">THE CREATIVE<br>POSSIBILITIES</span><p>Same<br>product.<br><em>New<br>energy.</em></p><span class="type-ad-foot">100% your kind of different. ↗</span></div>${creative.map(card).join('')}</div><div class="wall-foot"><span>ONE IDEA. EVERY WAY TO TELL IT.</span><a href="/showcase/">Explore the showcase <span>↗</span></a></div></section>
<section class="platform-strip"><span>MADE FOR THE PLACES<br>YOUR PEOPLE SCROLL.</span><div class="platform-name"><b class="meta-symbol">∞</b> Meta</div><div class="platform-name"><b>◎</b> Instagram</div><div class="platform-name"><b>♪</b> TikTok</div><div class="platform-name google"><b>G</b> Google Ads</div><div class="platform-name"><b class="youtube-icon">▶</b> YouTube</div></section>
<section class="possibilities section-wrap" id="possibilities"><div class="section-head"><div><div class="section-kicker">01 / THE CREATIVE POSSIBILITIES</div><h2>A whole creative team.<br><em>One very good tab.</em></h2></div><p>For the first idea, the fiftieth variation,<br>and everything that happens in between.</p></div><div class="feature-grid"><a class="feature-card feature-orange" href="/showcase/?format=Static%20ads"><div class="feature-top"><span class="line-icon">▧</span><span>↗</span></div><h3>Make them stop.<br>Then make them look.</h3><p>Turn product photos into static ads<br>that feel unmistakably yours.</p><div class="mini-composition"><div class="mini-ad">${art(creative[0])}</div><div class="mini-ad second"><span>Every day.<br><em>A little<br>brighter.</em></span><b>ÉCLAT SKIN</b></div></div><span class="feature-caption">STATIC ADS & CAROUSELS</span></a><a class="feature-card feature-cream" href="/showcase/?format=UGC%20videos"><div class="feature-top"><span class="line-icon">▷</span><span>↗</span></div><h3>A human touch.<br>A fresh perspective.</h3><p>Explore creator-style videos with<br>hooks that start a conversation.</p><div class="ugc-preview">${art(creative[1])}<span class="caption-bubble">your new morning ritual ☀</span><span class="concept-label">UGC CONCEPT</span></div><span class="feature-caption">UGC & PRODUCT VIDEOS</span></a><a class="feature-card feature-green" href="#workflow"><div class="feature-top"><span class="line-icon">⌘</span><span>↗</span></div><h3>Keep the ideas.<br>Lose the busywork.</h3><p>A clearer path from your first brief<br>to your team's favorite creative.</p><div class="workflow-mini"><div><i>✳</i><span>New product brief</span><b>✓</b></div><span class="connector">↓</span><div><i>▧</i><span>Create variations</span><b>✓</b></div><span class="connector">↓</span><div><i>◎</i><span>Ready for review</span><span class="avatars"><b>A</b><b>J</b></span></div></div><span class="feature-caption">WORKFLOWS & COLLABORATION</span></a></div></section>
<section class="workflow-section" id="workflow"><div class="section-wrap workflow-layout"><div class="workflow-copy"><div class="section-kicker">02 / FROM IDEA TO OUT THERE</div><h2>Goodbye, blank page.<br><em>Hello, possibilities.</em></h2><p>You bring the product. Adcraft helps you<br>find a whole new way to introduce it.</p><div class="steps"><button class="step active" data-step="0" aria-pressed="true"><span class="step-number">01</span><span><strong>Start with what you have.</strong><small>A product photo. A link. A half-formed idea.</small></span></button><button class="step" data-step="1" aria-pressed="false"><span class="step-number">02</span><span><strong>Find your creative direction.</strong><small>Explore hooks, formats, and new perspectives.</small></span></button><button class="step" data-step="2" aria-pressed="false"><span class="step-number">03</span><span><strong>Make it yours. Send it out.</strong><small>Fine-tune, review, and prepare every format.</small></span></button></div></div><div class="demo-window"><div class="demo-title"><span class="brand-symbol">✳</span><span>Creative workspace</span><span class="demo-badge">SAMPLE WORKFLOW</span></div><div class="demo-content" id="demo-content" aria-live="polite"></div><div class="demo-bottom"><span><i class="little-dot"></i> A new idea starts here</span><span>✧ Powered by your imagination</span></div></div></div></section>
<section class="formats-section section-wrap"><div class="section-kicker">03 / YOUR BRAND, EVERYWHERE</div><div class="section-head"><h2>One brand.<br><em>Never one-note.</em></h2><a class="text-button" href="/showcase/">See what’s possible ${arrow}</a></div><div class="format-row"><span class="format-statement">A fresh angle for<br>every kind of scroll.</span><div><b>9:16</b><span>Stories & Reels</span></div><div><b>1:1</b><span>Feed favorites</span></div><div><b>4:5</b><span>Room to stand out</span></div><div><b>16:9</b><span>The bigger picture</span></div></div></section>${cta()}</main>`;
const showcase=()=>`<main id="main"><section class="page-hero"><div class="eyebrow"><span class="tiny-star">✳</span> THE CREATIVE SHOWCASE</div><h1>A little inspiration.<br><em>A lot of potential.</em></h1><p>Different products. Fresh perspectives. Explore a few directions<br class="desktop-break"> your next campaign could take.</p></section><section class="section-wrap gallery-section"><div class="gallery-toolbar"><div class="filter-tabs" role="group" aria-label="Filter creative format">${['All creative','Static ads','UGC videos','Product videos'].map((v,i)=>`<button data-filter="${v}" class="${!i?'active':''}" aria-pressed="${!i}">${v}</button>`).join('')}</div><span class="gallery-count" aria-live="polite">4 creative concepts</span></div><div class="gallery-grid"></div><div class="gallery-note"><span>✳</span><p>A creative starting point, not a finished campaign.<br>These sample concepts show the look, feel, and storytelling possibilities.</p></div></section>${cta()}</main>`;
const pricing=()=>`<main id="main"><section class="page-hero"><div class="eyebrow"><span class="tiny-star">✳</span> ROOM FOR YOUR NEXT BIG IDEA</div><h1>Small beginnings.<br><em>Big creative energy.</em></h1><p>A plan for your first campaign, your next launch,<br class="desktop-break"> and the team making it all happen.</p><div class="billing-switch" role="group" aria-label="Billing period"><button data-billing="monthly" class="active" aria-pressed="true">Monthly</button><button data-billing="yearly" aria-pressed="false">Yearly <span>Save 20%</span></button></div><p class="pricing-disclaimer">Planned launch pricing. No payment or subscription is available yet.</p></section><section class="pricing-grid section-wrap">${[{name:'Starter',desc:'For your first “let’s try this.”',price:29,items:['1 brand workspace','Static ads & creative concepts','UGC video generation access','Core export formats','Personal asset library']},{name:'Studio',desc:'For brands with more to say.',price:79,popular:true,items:['3 brand workspaces','Everything in Starter','More generation capacity','Creative variations & resizing','Team review & approvals']},{name:'Agency',desc:'For a whole world of brands.',price:199,items:['10 brand workspaces','Everything in Studio','Client review workspaces','Shared templates & brand kits','Priority generation queue']}].map(p=>`<article class="price-card ${p.popular?'popular':''}">${p.popular?'<div class="popular-label">A LITTLE MORE ROOM TO CREATE ✳</div>':''}<span class="plan-name">${p.name}</span><p>${p.desc}</p><div class="plan-price"><span class="price-value" data-price="${p.price}">$${p.price}</span><span>/ month</span></div><span class="billing-detail">Billed monthly</span><a class="button ${p.popular?'button-orange':'button-outline'}" href="#compare">Explore ${p.name} ${arrow}</a><span class="included-label">WHAT’S PLANNED</span><ul>${p.items.map(x=>`<li><span>✓</span>${x}</li>`).join('')}</ul></article>`).join('')}</section><p class="credit-note">Generation credits and usage limits will be confirmed before launch. Ad spend is separate.</p><section class="section-wrap compare-section" id="compare"><div class="section-kicker">THE DETAILS, AT A GLANCE</div><h2>Find your <em>creative fit.</em></h2><div class="table-scroll"><table><caption class="sr-only">Planned feature comparison across pricing plans</caption><thead><tr><th>Made for the way you work</th><th>Starter</th><th>Studio</th><th>Agency</th></tr></thead><tbody>${[['Brand workspaces','1','3','10'],['Static ads & UGC concepts','Included','Included','Included'],['Product asset library','Included','Included','Included'],['Creative variations','Basic','Expanded','Expanded'],['Review & approvals','—','Team','Team & client'],['Shared brand templates','—','—','Included']].map(row=>`<tr>${row.map((v,i)=>`<${i?'td':'th'} ${!i?'scope="row"':''}>${v}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table></div></section><section class="faq-section section-wrap"><div><div class="section-kicker">A FEW GOOD QUESTIONS</div><h2>Glad <em>you asked.</em></h2></div><div class="faqs">${[['Can I subscribe now?','Not yet. These are planned launch tiers, shared so you can explore the product direction. There is no checkout, charge, or active subscription in this preview.'],['How will generation credits work?','Image and video generation have different costs. Final credit allowances, video durations, and usage limits will be published before paid plans become available.'],['Does pricing include advertising spend?','No. Creative generation and workspace access are separate from the budgets you spend on Meta, TikTok, Google, or other advertising platforms.'],['Can I use my own product photos and branding?','That is central to the planned experience: your product assets, brand colors, tone, and creative direction in one workspace.'],['Will you publish and manage my campaigns?','Campaign connections, reporting, and publishing are on the product roadmap. This first preview focuses on the creative experience.']].map(([q,a])=>`<details><summary>${q}<span>+</span></summary><p>${a}</p></details>`).join('')}</div></section>${cta()}</main>`;
const demoSteps=[`<span class="workspace-label">LET’S MEET YOUR PRODUCT</span><h3>Every great ad starts<br>with a little something.</h3><div class="product-import"><div class="product-thumb"></div><div><strong>The Everyday Serum</strong><span>Éclat Skin · Skincare</span><small>Product photo added <b>✓</b></small></div></div><div class="mock-field"><span>YOUR CREATIVE BRIEF</span><p>Golden-hour glow, every single day.<br>Keep it warm, simple, and a little playful.</p></div><button class="button button-dark demo-next" data-next="1">Find my creative direction ${arrow}</button>`,`<span class="workspace-label">A FEW WAYS TO TELL YOUR STORY</span><h3>Same product.<br>A fresh point of view.</h3><div class="direction-list"><div><span>01</span><strong>Your everyday glow</strong><small>Product-led · Warm & minimal</small></div><div><span>02</span><strong>The routine worth sharing</strong><small>Creator-led · Honest & personal</small></div><div><span>03</span><strong>A little golden hour</strong><small>Lifestyle · Bright & playful</small></div></div><button class="button button-dark demo-next" data-next="2">Explore the variations ${arrow}</button>`,`<span class="workspace-label">READY FOR YOUR PERSONAL TOUCH</span><h3>One idea.<br>Every way to share it.</h3><div class="demo-variants">${[creative[0],creative[1]].map(c=>`<button data-creative="${c.id}" aria-label="View ${c.title}">${art(c)}</button>`).join('')}</div><a class="button button-dark" href="/showcase/">See the creative showcase ${arrow}</a>`];
function render(){document.getElementById('app').innerHTML=nav()+(isPricing?pricing():isShowcase?showcase():home())+footer()+`<dialog class="creative-dialog" aria-labelledby="dialog-title"><button class="dialog-close" aria-label="Close concept">×</button><div id="dialog-content"></div></dialog>`;document.querySelector('.menu-toggle').onclick=e=>{let open=e.currentTarget.getAttribute('aria-expanded')!=='true';e.currentTarget.setAttribute('aria-expanded',open);document.querySelector('.desktop-nav').classList.toggle('open',open)};document.querySelectorAll('.desktop-nav a').forEach(a=>a.onclick=()=>{document.querySelector('.desktop-nav').classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false')});if(isShowcase)setFilter(new URLSearchParams(location.search).get('format')||'All creative');if(!isPricing&&!isShowcase)setStep(0);document.querySelectorAll('[data-billing]').forEach(b=>b.onclick=()=>setBilling(b.dataset.billing));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>setFilter(b.dataset.filter));document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>setStep(+b.dataset.step));document.querySelector('.dialog-close').onclick=()=>document.querySelector('dialog').close();document.querySelector('dialog').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close()});bindCards();}
function bindCards(){document.querySelectorAll('[data-creative]').forEach(b=>b.onclick=()=>openCreative(b.dataset.creative));document.querySelectorAll('[data-next]').forEach(b=>b.onclick=()=>setStep(+b.dataset.next));}
function openCreative(id){let c=creative.find(x=>x.id===id);document.getElementById('dialog-content').innerHTML=`<div class="dialog-art">${art(c)}</div><div class="dialog-copy"><div class="section-kicker">${c.type.toUpperCase()} · SAMPLE CONCEPT</div><h2 id="dialog-title">${c.title}</h2><p>${c.description}</p><dl><dt>THE OPENING HOOK</dt><dd>“${c.hook}”</dd><dt>THE CALL TO ACTION</dt><dd>${c.cta}</dd><dt>THE FORMAT</dt><dd>${c.format}</dd></dl><p class="dialog-note">Illustrative creative direction. Video concepts are storyboards, not playable videos.</p><button class="button button-dark close-inside">Keep exploring ${arrow}</button></div>`;document.querySelector('.close-inside').onclick=()=>document.querySelector('dialog').close();document.querySelector('dialog').showModal();}
function setFilter(filter){const valid=['All creative','Static ads','UGC videos','Product videos'];if(!valid.includes(filter))filter='All creative';document.querySelectorAll('[data-filter]').forEach(b=>{let active=b.dataset.filter===filter;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});const shown=creative.filter(c=>filter==='All creative'||c.type===filter);document.querySelector('.gallery-grid').innerHTML=shown.map(c=>`<article>${card(c)}<h2>${c.title}</h2><p>${c.brand} <span>·</span> ${c.format}</p></article>`).join('');document.querySelector('.gallery-count').textContent=`${shown.length} creative concept${shown.length===1?'':'s'}`;bindCards();}
function setStep(step){document.querySelectorAll('[data-step]').forEach(b=>{let active=+b.dataset.step===step;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});document.getElementById('demo-content').innerHTML=demoSteps[step];bindCards();}
function setBilling(period){document.querySelectorAll('[data-billing]').forEach(b=>{let active=b.dataset.billing===period;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});document.querySelectorAll('[data-price]').forEach(el=>{const amount=+el.dataset.price;el.textContent='$'+(period==='yearly'?(amount*.8).toFixed(2):amount)});document.querySelectorAll('.billing-detail').forEach((el,i)=>{const amount=+document.querySelectorAll('[data-price]')[i].dataset.price;el.textContent=period==='yearly'?`$${(amount*.8*12).toFixed(2)} billed yearly`:'Billed monthly'});}
render();
